package net.civeira.phylax.feature.observe.observabilityconfig.domain.valueholder;

import java.util.Optional;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;
import org.mockito.Mockito;

import net.civeira.phylax.common.value.validation.ConstraintFailList;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.ObservabilityConfig;
import net.civeira.phylax.feature.observe.observabilityconfig.domain.valueobject.RetentionDaysMetricsVO;

class RetentionDaysMetricsValueHolderUnitTest {

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign plain values on the holder of retention days metrics of observability config")
  void test_retention_days_metrics_value_holder_assign_plain_value() {
    Object holder = new Object();
    RetentionDaysMetricsValueHolder<Object> value = new RetentionDaysMetricsValueHolder<>(holder);
    Assertions.assertSame(holder, value.retentionDaysMetrics(1), "Setters must return the holder");
    Assertions.assertTrue(value.getRetentionDaysMetricsValue().isPresent(),
        "The plain value must be stored");
    Assertions.assertEquals(1, value.getRetentionDaysMetrics().orElse(null),
        "The plain value must be recovered");
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test assign value objects on the holder of retention days metrics of observability config")
  void test_retention_days_metrics_value_holder_assign_value_object() {
    Object holder = new Object();
    RetentionDaysMetricsValueHolder<Object> value = new RetentionDaysMetricsValueHolder<>(holder);
    RetentionDaysMetricsVO vo = RetentionDaysMetricsVO.from(1);
    Assertions.assertFalse(value.getRetentionDaysMetricsValue().isPresent(),
        "A new holder must be empty");
    Assertions.assertSame(holder, value.retentionDaysMetrics(vo), "Setters must return the holder");
    Assertions.assertSame(vo, value.getRetentionDaysMetricsValue().orElseThrow());
    Assertions.assertSame(holder, value.retentionDaysMetrics(Optional.empty()));
    Assertions.assertFalse(value.getRetentionDaysMetricsValue().isPresent(),
        "An empty optional must clear the value");
    Assertions.assertSame(holder, value.retentionDaysMetrics(Optional.of(vo)));
    Assertions.assertSame(vo, value.getRetentionDaysMetricsValue().orElseThrow());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test read the value of the holder of retention days metrics of observability config against the original")
  void test_retention_days_metrics_value_holder_read() {
    Object holder = new Object();
    RetentionDaysMetricsValueHolder<Object> value = new RetentionDaysMetricsValueHolder<>(holder);
    RetentionDaysMetricsVO vo = RetentionDaysMetricsVO.from(1);
    RetentionDaysMetricsVO other = RetentionDaysMetricsVO.from(1);
    ObservabilityConfig original = Mockito.mock(ObservabilityConfig.class);
    Mockito.when(original.getRetentionDaysMetricsValue()).thenReturn(other);
    ConstraintFailList fails = new ConstraintFailList();
    Assertions.assertSame(other, value.readRetentionDaysMetrics(Optional.of(original), fails),
        "Without value, the original must be used");
    Assertions.assertTrue(fails.isEmpty());
    Assertions.assertNull(value.readRetentionDaysMetrics(Optional.empty(), fails),
        "Without value and original there is no result");
    Assertions.assertFalse(fails.isEmpty(), "A required value must be reported as missing");
    value.retentionDaysMetrics(vo);
    ConstraintFailList others = new ConstraintFailList();
    Assertions.assertSame(vo, value.readRetentionDaysMetrics(Optional.of(original), others),
        "With value, the original is ignored");
    Assertions.assertSame(vo, value.readRetentionDaysMetrics(Optional.empty(), others));
    Assertions.assertTrue(others.isEmpty());
  }

  /**
   * @autogenerated ValueHolderGenerator
   */
  @Test
  @DisplayName("Test unset the value of the holder of retention days metrics of observability config")
  void test_retention_days_metrics_value_holder_unset() {
    Object holder = new Object();
    RetentionDaysMetricsValueHolder<Object> value = new RetentionDaysMetricsValueHolder<>(holder);
    RetentionDaysMetricsVO vo = RetentionDaysMetricsVO.from(1);
    value.retentionDaysMetrics(vo);
    Assertions.assertSame(holder,
        value.unsetRetentionDaysMetricsIfMatches("retentionDaysMetrics_other"));
    Assertions.assertTrue(value.getRetentionDaysMetricsValue().isPresent(),
        "Other field name must keep the value");
    Assertions.assertSame(holder, value.unsetRetentionDaysMetricsIfMatches("retentionDaysMetrics"));
    Assertions.assertFalse(value.getRetentionDaysMetricsValue().isPresent(),
        "The field name must clear the value");
    value.retentionDaysMetrics(vo);
    Assertions.assertSame(holder, value.unsetRetentionDaysMetrics());
    Assertions.assertFalse(value.getRetentionDaysMetricsValue().isPresent(),
        "Unset must clear the value");
  }
}
